// Writes CREDITS.md from the same list the demo uses, so credits can't drift.
import { writeFileSync, existsSync } from "node:fs";
import { coreSamples } from "../src/content/lithology-samples.ts";

const used = coreSamples.filter((s) => existsSync(new URL(`../public${s.file}`, import.meta.url)));
const lines = [
  "# Credits",
  "",
  "Generated by `npm run credits` from `src/content/lithology-samples.ts`.",
  "",
  "## Core photos (Demo 2: lithology helper)",
  "",
  "All from Wikimedia Commons. Resized and stripped of metadata for the web; otherwise unchanged.",
  "",
  ...used.map((s) => `- **${s.label}**: ${s.sourceSays} Photo by ${s.author}. Licence: ${s.licenseUrl ? `[${s.license}](${s.licenseUrl})` : s.license}. Source: <${s.sourceUrl}>`),
  "",
  "## Software",
  "",
  "- Fonts: Inter and JetBrains Mono (SIL Open Font License), self-hosted via Fontsource.",
  "- Three.js (MIT), Papa Parse (MIT), SheetJS Community Edition (Apache-2.0), Astro (MIT), Tailwind CSS (MIT).",
  "",
  "## Data",
  "",
  "- `public/sample-drill-log.csv` is synthetic, generated by `scripts/make-sample.ts`. No real drilling data is used anywhere on this site.",
  "",
];
writeFileSync(new URL("../CREDITS.md", import.meta.url), lines.join("\n"));
console.log(`CREDITS.md: ${used.length} photos`);
